//! Cargo-driven `aclui.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is aclui-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x78050000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff74000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff74000000u64)),
        o => panic!("aclui-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "import:user32", "import:gdi32", "import:comctl32", "import:ole32", "import:oleaut32", "import:advapi32", "import:uxtheme", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "x86_64" => &["body", "import:user32", "import:gdi32", "import:comctl32", "import:ole32", "import:oleaut32", "import:advapi32", "import:uxtheme", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "import:user32", "import:gdi32", "import:comctl32", "import:ole32", "import:oleaut32", "import:advapi32", "import:uxtheme", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/aclui",
        "dll/win32/aclui",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "vendor/zlib/include",
        "sdk/lib/tdilib",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "SUPPORT_UXTHEME",
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("aclui-rust")
        .c_from_compile_db("aclui_shims", &["dll/win32/aclui/rust_varargs_shim.c", "dll/win32/aclui/guid.c"])
        .rc("dll/win32/aclui/aclui.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/aclui/aclui.spec", "aclui.dll")
        .spec_stubs()
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/uxtheme/uxtheme.spec", "uxtheme.dll", "uxtheme")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
